// Differential checks of LoopState-pbo.js against Lean, generated by leanscript --check
import * as M from "./LoopState-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("fib(0)", () => M.fib(0), "0", false);
check("fib(1)", () => M.fib(1), "1", false);
check("fib(2)", () => M.fib(2), "1", false);
check("fib(5)", () => M.fib(5), "5", false);
check("fib(13)", () => M.fib(13), "233", false);
check("firstAbove(0, 0)", () => M.firstAbove(0, 0), "0", false);
check("firstAbove(0, 2)", () => M.firstAbove(0, 2), "0", false);
check("firstAbove(1, 1)", () => M.firstAbove(1, 1), "0", false);
check("firstAbove(2, 0)", () => M.firstAbove(2, 0), "1", false);
check("firstAbove(0, 13)", () => M.firstAbove(0, 13), "0", false);
check("firstAbove(1, 5)", () => M.firstAbove(1, 5), "0", false);
check("firstAbove(2, 2)", () => M.firstAbove(2, 2), "0", false);
check("firstAbove(5, 1)", () => M.firstAbove(5, 1), "2", false);
check("firstAbove(13, 0)", () => M.firstAbove(13, 0), "1", false);
check("firstAbove(2, 13)", () => M.firstAbove(2, 13), "0", false);
check("firstAbove(5, 5)", () => M.firstAbove(5, 5), "3", false);
check("firstAbove(13, 2)", () => M.firstAbove(13, 2), "2", false);
check("firstAbove(13, 13)", () => M.firstAbove(13, 13), "4", false);

console.log(`LoopState-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
